import { accessories } from "./accessories";

function createProductFromAccessory(accessory) {
  return {
    id: accessory.id,
    name: accessory.name,
    category: accessory.category,
    price: accessory.price,
    currency: "NPR",
    description: accessory.description,
    previewUrl: accessory.thumbnailUrl,
    thumbnailUrl: accessory.thumbnailUrl,
    tryOnImageUrl: accessory.thumbnailUrl,
    modelUrl: accessory.modelUrl,
    accessoryId: accessory.id,
    arSupported: accessory.arSupported
  };
}

export function createProductCatalog(total = 100) {
  return accessories
    .slice(0, total)
    .map((accessory) => createProductFromAccessory(accessory));
}

export const fallbackProducts = createProductCatalog(100);